"""Backend-only Kernel credential transport; no secret readback or mutation retries.

Contract: https://kernel.sh/docs/vaults/credentials and /vaults/fill.
Collection actions are bearer capabilities: callers must keep returned URLs on
the authenticated private collection surface. This module never logs payloads.
"""
from datetime import datetime
import re
import time
from urllib.parse import quote, urlsplit

import requests
from requests.adapters import HTTPAdapter

from vault.store import AccessError
from .kernel_client import API_URL
from .kernel_diagnostics import operation

FIELD_TYPES = frozenset({'text', 'email', 'password', 'totp'})
FILL_ERROR_CODES = frozenset({'target_changed', 'element_not_found',
    'ambiguous_selector', 'element_not_editable', 'option_not_found',
    'timeout', 'execution_failed'})
_FIELD_NAME = re.compile(r'[A-Za-z][A-Za-z0-9_]{0,63}\Z')
_REFERENCE = re.compile(r'[A-Za-z0-9][A-Za-z0-9_.:-]{0,254}\Z')
_MAX_VALUE_BYTES = 16384


class _ResponseError(Exception):
    pass


def _argument(condition):
    if not condition:
        raise AccessError('The Kernel vault request has unsupported fields or values.', 400)


def _response(condition):
    if not condition:
        raise _ResponseError()


def _reference(value):
    _argument(isinstance(value, str) and _REFERENCE.fullmatch(value) is not None)
    return quote(value, safe='')


def _text(value, limit=_MAX_VALUE_BYTES, *, empty=False):
    try:
        return (isinstance(value, str) and (empty or bool(value)) and
                len(value.encode('utf-8')) <= limit)
    except UnicodeError:
        return False


def _field_name(value):
    return isinstance(value, str) and _FIELD_NAME.fullmatch(value) is not None


def _definitions(fields, *, incoming=False):
    check = _argument if incoming else _response
    check(isinstance(fields, list) and 1 <= len(fields) <= 32)
    result = []
    names = set()
    for field in fields:
        check(isinstance(field, dict))
        if incoming:
            check(set(field) <= {'name', 'label', 'type', 'required', 'sensitive', 'value'})
        name, kind = field.get('name'), field.get('type')
        required, sensitive = field.get('required', True), field.get('sensitive', True)
        check(_field_name(name) and name not in names and isinstance(kind, str) and kind in FIELD_TYPES)
        check(type(required) is bool and type(sensitive) is bool)
        # A missing sensitivity flag in a provider response never authorizes a
        # public value; require the complete immutable server definition.
        if not incoming:
            check('required' in field and 'sensitive' in field)
        check(kind not in ('password', 'totp') or sensitive is True)
        clean = {'name': name, 'type': kind, 'required': required, 'sensitive': sensitive}
        label = field.get('label')
        if label is not None:
            check(_text(label, 128) and label == label.strip() and
                  not any(ord(char) < 32 or ord(char) == 127 for char in label))
            clean['label'] = label
        if incoming and 'value' in field:
            check(_text(field['value']))
            clean['value'] = field['value']
        names.add(name)
        result.append(clean)
    return result


def _timestamp(value):
    _response(isinstance(value, str) and len(value) <= 64)
    parsed = datetime.fromisoformat(value.replace('Z', '+00:00'))
    _response(parsed.tzinfo is not None)
    return value


def _vault(body):
    _response(isinstance(body, dict))
    _response(isinstance(body.get('id'), str) and _REFERENCE.fullmatch(body['id']) is not None)
    _response(isinstance(body.get('name'), str) and _REFERENCE.fullmatch(body['name']) is not None)
    result = {'id': body['id'], 'name': body['name']}
    for field in ('created_at', 'updated_at'):
        if field in body:
            result[field] = _timestamp(body[field])
    return result


def _item(body, *, key=None, include_public_values=False):
    _response(isinstance(body, dict) and body.get('type') == 'credential')
    _response(isinstance(body.get('id'), str) and _REFERENCE.fullmatch(body['id']) is not None)
    _response(isinstance(body.get('key'), str) and _REFERENCE.fullmatch(body['key']) is not None)
    _response(key is None or body['key'] == key)
    _response(type(body.get('version')) is int and body['version'] >= 1)
    spec, state = body.get('spec'), body.get('state')
    _response(isinstance(spec, dict) and spec.get('provider') == 'kernel')
    _response(isinstance(state, dict) and state.get('provider') == 'kernel')
    _response(state.get('status') in ('pending_collection', 'ready'))
    definitions = _definitions(spec.get('fields'))
    clean_spec = {'provider': 'kernel', 'fields': definitions}
    if spec.get('description') is not None:
        _response(_text(spec['description'], empty=True))
        clean_spec['description'] = spec['description']
    values = state.get('fields')
    _response(isinstance(values, dict) and set(values) == {field['name'] for field in definitions})
    clean_values = {}
    for definition in definitions:
        field = values[definition['name']]
        _response(isinstance(field, dict) and type(field.get('has_value')) is bool)
        clean = {'has_value': field['has_value']}
        if (include_public_values and definition['sensitive'] is False and
                definition['type'] in ('text', 'email') and field['has_value']):
            _response(_text(field.get('value')))
            clean['value'] = field['value']
        clean_values[definition['name']] = clean
    if state['status'] == 'ready':
        _response(all(not field['required'] or clean_values[field['name']]['has_value']
                      for field in definitions))
    operations = body.get('available_operations')
    _response(isinstance(operations, list))
    clean_operations = []
    for advertised in operations:
        _response(isinstance(advertised, dict))
        # Unknown provider operations are never exposed or invoked here.
        if advertised.get('type') in ('collect', 'fill'):
            _response(advertised['type'] not in {entry['type'] for entry in clean_operations})
            clean_operations.append({'type': advertised['type']})
    result = {'id': body['id'], 'key': body['key'], 'type': 'credential',
              'version': body['version'], 'spec': clean_spec,
              'state': {'provider': 'kernel', 'status': state['status'], 'fields': clean_values},
              'available_operations': clean_operations}
    action = body.get('action')
    if action is not None:
        _response(isinstance(action, dict) and action.get('name') == 'collect')
        _response(_text(action.get('url')) and
                  not any(ord(char) < 32 or ord(char) == 127 for char in action['url']))
        parsed = urlsplit(action['url'])
        _response(parsed.scheme == 'https' and parsed.hostname == 'vault.kernel.sh' and
                  parsed.username is None and parsed.password is None and parsed.port in (None, 443))
        result['action'] = {'name': 'collect', 'url': action['url'],
                            'expires_at': _timestamp(action.get('expires_at'))}
    for field in ('created_at', 'updated_at'):
        if field in body:
            result[field] = _timestamp(body[field])
    return result


def _fill_result(body, count):
    _response(isinstance(body, dict) and body.get('type') == 'fill')
    status, fields = body.get('status'), body.get('fields')
    _response(status in ('completed', 'failed', 'unknown'))
    _response(isinstance(fields, list) and len(fields) == count)
    result, stopped = [], False
    for index, field in enumerate(fields):
        _response(isinstance(field, dict) and type(field.get('index')) is int and field['index'] == index)
        outcome = field.get('status')
        _response(outcome in ('filled', 'failed', 'unknown', 'not_attempted'))
        _response(outcome == 'not_attempted' if stopped else outcome != 'not_attempted')
        clean = {'index': index, 'status': outcome}
        if field.get('error_code') is not None:
            _response(field['error_code'] in FILL_ERROR_CODES and outcome in ('failed', 'unknown'))
            clean['error_code'] = field['error_code']
        result.append(clean)
        stopped = stopped or outcome in ('failed', 'unknown')
    outcomes = {field['status'] for field in result}
    _response((status == 'completed' and outcomes == {'filled'}) or
              (status == 'failed' and 'failed' in outcomes and 'unknown' not in outcomes) or
              (status == 'unknown' and 'unknown' in outcomes))
    return {'type': 'fill', 'status': status, 'fields': result}


class KernelVaultClient:
    """Uses a protected KernelClient key; never exposes an API-key argument.

    All returned collection actions and opted-in public values are backend-only.
    Caller authorization must precede fill; exact page_url is selection, not ACL.
    """
    def __init__(self, kernel_client, *, project=None):
        if project is not None:
            _reference(project)
        self.kernel = kernel_client
        self.project = project
        # A separate non-environment session prevents cookies, custom retry
        # adapters or ambient proxies on another client from affecting secrets.
        self.http = requests.Session()
        self.http.trust_env = False
        self.http.mount('https://', HTTPAdapter(max_retries=0))

    def _request(self, method, path, route, *, body=None, params=None, parser=None,
                 absent=False, timeout=15, expected=(200,)):
        attempted = False
        with operation(self.kernel, 'vault_' + method.lower()) as diagnostic:
            event = {'method': method, 'route': route, 'upstream_status': None,
                     'timeout_seconds': timeout}
            started = time.monotonic()
            try:
                key = self.kernel.key()
                if not isinstance(key, str) or not key:
                    raise AccessError('The protected Kernel service key is missing.', 503)
                headers = {'Authorization': 'Bearer ' + key, 'Accept': 'application/json'}
                if self.project is not None:
                    headers['X-Kernel-Project'] = self.project
                diagnostic.event['requests'].append(event)
                attempted = True
                response = self.http.request(method, API_URL + path, headers=headers,
                    json=body, params=params, timeout=timeout, allow_redirects=False)
                status = response.status_code
                if type(status) is not int or not 100 <= status <= 599:
                    raise _ResponseError()
                event['upstream_status'] = status
                if absent and status == 404:
                    return None
                if status not in expected:
                    code, exposed_status = {
                        400: ('invalid_request', 400), 401: ('authentication_failed', 503),
                        403: ('forbidden', 403), 404: ('not_found', 404),
                        409: ('conflict', 409), 422: ('invalid_request', 400),
                        429: ('rate_limited', 429),
                    }.get(status, ('upstream_error', 503))
                    # Do not inspect an error body, response headers, or URL.
                else:
                    return parser(response.json()) if parser is not None else True
            except (ValueError, TypeError, KeyError, _ResponseError):
                code, exposed_status = 'invalid_response', 502
            except requests.Timeout:
                code, exposed_status = 'timeout', 503
            except requests.ConnectionError:
                code, exposed_status = 'connection_error', 503
            except Exception:
                # Provider exceptions can include submitted secrets. Never pass
                # the object/string/traceback to the diagnostic logger.
                code, exposed_status = 'transport_error', 503
            finally:
                event['elapsed_ms'] = round((time.monotonic() - started) * 1000, 2)
            diagnostic.failure(kind=code)
            error = diagnostic.access_error('Kernel vault request could not be confirmed.', exposed_status)
            error.kernel_vault_code = code
            error.mutation_attempted = attempted and method in ('POST', 'PUT', 'PATCH', 'DELETE')
            raise error from None

    @staticmethod
    def _path(vault, key=None):
        path = '/vaults/' + _reference(vault)
        return path if key is None else path + '/items/' + _reference(key)

    def create_vault(self, name):
        _reference(name)
        def parse(body):
            result = _vault(body)
            _response(result['name'] == name)
            return result
        return self._request('POST', '/vaults', '/vaults', body={'name': name},
                             parser=parse, expected=(200, 201))

    def get_vault(self, vault):
        def parse(body):
            result = _vault(body)
            _response(vault in (result['id'], result['name']))
            return result
        return self._request('GET', self._path(vault), '/vaults/{vault}', parser=parse, absent=True)
"""Sanitized operator diagnostics for the protected Kernel API boundary."""
from contextlib import contextmanager
from contextvars import ContextVar
import hashlib
import json
import logging
from pathlib import Path
import re
import time
import traceback
from urllib.parse import quote, quote_plus, urlsplit
import uuid

import requests

from vault.store import AccessError

logger = logging.getLogger(__name__)
_active = ContextVar('clanker_kernel_diagnostic', default=None)
_URL = re.compile(r'\b(?:https?|wss?)://[^\s<>\"\']+', re.IGNORECASE)
_BEARER = re.compile(r'\bBearer\s+[^\s\"\',;]+', re.IGNORECASE)


def _http_failed(request):
    status = request['upstream_status']
    return status is not None and status >= 300 and not (
        status == 404 and request['method'] in ('GET', 'DELETE'))


def current(client):
    diagnostic = _active.get()
    return diagnostic if diagnostic is not None and diagnostic.client is client else None


@contextmanager
def operation(client, name, task_id=None):
    # Deletion and its verification read form one operation, including its error
    # reference. ContextVars keep concurrent requester operations independent.
    existing = current(client)
    if existing is not None:
        yield existing
        return
    diagnostic = KernelDiagnostic(client, name, task_id)
    token = _active.set(diagnostic)
    try:
        yield diagnostic
    finally:
        _active.reset(token)


class KernelDiagnostic:
    def __init__(self, client, name, task_id):
        self.client = client
        self.reference = uuid.uuid4().hex
        self.secrets = set()
        self.logged = False
        self.event = {'event': 'kernel_upstream_failure', 'provider': 'kernel',
                      'operation': name, 'diagnostic_ref': self.reference, 'requests': []}
        if task_id is not None:
            self.event['task_ref'] = hashlib.sha256(str(task_id).encode()).hexdigest()[:24]

    def remember_secret(self, value):
        if isinstance(value, str) and value:
            self.secrets.update((value, quote(value, safe=''), quote_plus(value),
                                 json.dumps(value)[1:-1]))

    def text(self, value, limit=1000):
        # Sanitize BEFORE constructing a LogRecord: log formatters may run in a
        # different thread, and ordinary profile redaction can be switched off.
        try:
            from agent.redact import redact_sensitive_text
            text = str(value).replace('\\/', '/')
            for secret in sorted(self.secrets, key=len, reverse=True):
                text = text.replace(secret, '[REDACTED]')
            if len(text) > 8192:
                return '[oversized diagnostic text omitted]'
            text = _URL.sub('[REDACTED_URL]', text)
            text = _BEARER.sub('Bearer [REDACTED]', text)
            text = redact_sensitive_text(text, force=True, redact_url_credentials=True)
            return text[:limit]
        except Exception:
            return '[diagnostic text unavailable]'

    def error_fields(self, response):
        # Success records contain control capabilities; never inspect or log
        # them. Error bodies are untrusted: retain only scalar code/message.
        try:
            if len(response.content) > 8192:
                return {'format': 'oversized_body_omitted'}
            body = response.json()
        except Exception:
            return {'format': 'non_json'}
        if not isinstance(body, dict):
            return {'format': 'unsupported_json'}
        fields = {}
        for name in ('code', 'message', 'error'):
            value = body.get(name)
            if isinstance(value, (str, int)) and not isinstance(value, bool):
                fields[name] = self.text(value)
            elif name == 'error' and isinstance(value, dict):
                fields[name] = {key: self.text(value[key]) for key in ('code', 'message')
                               if isinstance(value.get(key), (str, int))}
        return fields

    def request(self, method, url, call, *args, **kwargs):
        authorization = kwargs.get('headers', {}).get('Authorization', '')
        if authorization.startswith('Bearer '):
            self.remember_secret(authorization[7:])
        path = urlsplit(url).path
        route = ('/browsers/{id}' if path.startswith('/browsers/') else
            '/proxies/{id}/check' if re.fullmatch(r'/proxies/[^/]+/check', path) else
            '/proxies/{id}' if re.fullmatch(r'/proxies/[^/]+', path) else
            path if path in ('/browsers', '/proxies') else '[other]')
        event = {'method': method, 'route': route, 'upstream_status': None,
                 'timeout_seconds': kwargs.get('timeout')}
        self.event['requests'].append(event)
        start = time.monotonic()
        try:
            response = call(url, *args, **kwargs)
            event['upstream_status'] = response.status_code
            for header in ('x-request-id', 'request-id'):
                value = response.headers.get(header)
                if isinstance(value, str) and re.fullmatch(r'[A-Za-z0-9_.:-]{1,128}', value):
                    event['provider_request_id'] = self.text(value, 128)
                    break
            expected_absence = response.status_code == 404 and method in ('GET', 'DELETE')
            if response.status_code >= 300 and not expected_absence:
                event['upstream_error'] = self.error_fields(response)
            return response
        except Exception as error:
            event['exception_type'] = type(error).__module__ + '.' + type(error).__name__
            raise
        finally:
            event['elapsed_ms'] = round((time.monotonic() - start) * 1000, 2)

    def failure(self, error=None, kind=None):
        if self.logged:
            return
        chain = []
        seen = set()
        while error is not None and id(error) not in seen and len(chain) < 6:
            seen.add(id(error))
            if kind is None:
                if isinstance(error, requests.Timeout):
                    kind = 'timeout'
                elif isinstance(error, requests.ConnectionError):
                    kind = 'connection_error'
            # A provider HTTP exception can repeat its raw body. The selected
            # HTTP error fields above already preserve the useful detail.
            http_error = any(_http_failed(request) for request in self.event['requests'])
            chain.append({'type': type(error).__module__ + '.' + type(error).__name__,
                          'message': '[see upstream_error]' if http_error else self.text(error),
                          'frames': [{'file': Path(frame.filename).name,
                                      'function': frame.name, 'line': frame.lineno}
                                     for frame in traceback.extract_tb(error.__traceback__)[-8:]]})
            error = error.__cause__ or error.__context__
        if kind is None and any(_http_failed(request) for request in self.event['requests']):
            kind = 'http_error'
        self.event.update(failure_kind=kind or 'provider_exception', exception_chain=chain)
        self.logged = True
        # No exception objects, raw headers/bodies, locals or tracebacks enter
        # the logging queue. json.dumps escapes control characters in messages.
        try:
            logger.warning('Kernel upstream failure %s', json.dumps(self.event, sort_keys=True))
        except Exception:
            pass  # A broken operator log sink must not alter provider outcomes.

    def access_error(self, message, status):
        error = AccessError(message + ' Reference: ' + self.reference + '.', status)
        error.diagnostic_ref = self.reference
        return error
"""Exact Kernel Vault wire contracts and payload-silent failure boundaries."""
from concurrent.futures import ThreadPoolExecutor
from copy import deepcopy
import hashlib
import json
import logging
from pathlib import Path
import sys
from urllib.parse import quote

import pytest
import requests

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / 'runtime'))
sys.path.insert(0, str(ROOT / 'hermes'))

from cloud_browser import kernel_client, kernel_vault_client
from vault.store import AccessError

KEY = 'synthetic-backend-key/+?'
SECRET = 'synthetic-unregistered-password-value'
PUBLIC = 'synthetic-owner@example.invalid'
COLLECTION = 'https://vault.kernel.sh/collect?token=synthetic-bearer-capability'
PAGE = 'https://fixture.example.invalid/login?state=synthetic-private-state#otp'
TIMESTAMP = '2026-10-08T15:00:00Z'
LOGGER = 'cloud_browser.kernel_diagnostics'
PROVIDER = 'class KernelBrowserProvider:\n    pass\n'


class Response:
    def __init__(self, status, body=None):
        self.status_code = status
        self.body = body
        self.json_calls = 0

    def json(self):
        self.json_calls += 1
        if isinstance(self.body, Exception):
            raise self.body
        return deepcopy(self.body)


class Session:
    def __init__(self):
        self.trust_env = True
        self.adapters = {}
        self.responses = []
        self.calls = []

    def mount(self, prefix, adapter):
        self.adapters[prefix] = adapter

    def request(self, method, url, **kwargs):
        self.calls.append((method, url, deepcopy(kwargs)))
        assert self.responses, 'Unexpected request or automatic retry'
        result = self.responses.pop(0)
        if isinstance(result, Exception):
            raise result
        if callable(result):
            result = result()
        return result


def credential(*, status='ready', version=1, action=False):
    result = {'id': 'item-fixture', 'key': 'login', 'type': 'credential', 'version': version,
        'created_at': TIMESTAMP, 'updated_at': TIMESTAMP,
        'spec': {'provider': 'kernel', 'description': 'Fixture Portal', 'fields': [
            {'name': 'username', 'type': 'email', 'required': True, 'sensitive': False,
             'label': 'Email address', 'value': SECRET},
            {'name': 'password', 'type': 'password', 'required': True, 'sensitive': True},
            {'name': 'seed', 'type': 'totp', 'required': False, 'sensitive': True}]},
        'state': {'provider': 'kernel', 'status': status, 'fields': {
            'username': {'has_value': True, 'value': PUBLIC},
            'password': {'has_value': status == 'ready', 'value': SECRET},
            'seed': {'has_value': True, 'value': SECRET}}},
        'available_operations': [{'type': 'collect', 'description': SECRET},
            *([{'type': 'fill', 'description': SECRET}] if status == 'ready' else [])],
        'unknown_raw_body': SECRET}
    if action:
        result['action'] = {'name': 'collect', 'url': COLLECTION,
                            'expires_at': TIMESTAMP, 'opaque_token': SECRET}
    return result


def fill_result(status='completed'):
    return {'type': 'fill', 'status': status, 'fields': [
        {'index': 0, 'status': 'filled', 'raw_value': SECRET},
        {'index': 1, 'status': 'filled' if status == 'completed' else status,
         **({} if status == 'completed' else {'error_code': 'target_changed'}),
         'raw_error': SECRET}], 'raw': SECRET}


@pytest.fixture
def client(tmp_path, monkeypatch, caplog):
    monkeypatch.setattr(kernel_client.requests, 'Session', Session)
    home = tmp_path / 'transport'
    plugin = home / '.clanker-cloud' / 'vendor' / 'kernel'
    plugin.mkdir(parents=True)
    (plugin / 'provider.py').write_text(PROVIDER)
    (home / '.env').write_text('KERNEL_API_KEY=' + KEY + '\n')
    monkeypatch.setattr(kernel_client, 'PROVIDER_SHA256', hashlib.sha256(PROVIDER.encode()).hexdigest())
    kernel = kernel_client.KernelClient(home, {'enabled': True, 'provider': 'kernel',
        'plugin_path': str(plugin), 'plugin_commit': kernel_client.COMMIT})
    caplog.set_level(logging.WARNING, logger=LOGGER)
    return kernel_vault_client.KernelVaultClient(kernel, project='project-fixture')


def assert_private(caplog, error=None):
    exposed = repr([record.__dict__ for record in caplog.records]) + (str(error) if error else '')
    for value in (KEY, quote(KEY, safe=''), SECRET, PUBLIC, COLLECTION, PAGE):
        assert value not in exposed
    for record in caplog.records:
        assert record.exc_info is None and record.exc_text is None
    events = [json.loads(record.getMessage().split('Kernel upstream failure ', 1)[1])
              for record in caplog.records if record.name == LOGGER]
    for event in events:
        assert event['exception_chain'] == []
        assert all('upstream_error' not in request for request in event['requests'])
    return events


def test_backend_key_private_session_project_and_wire_routes(client, monkeypatch):
    monkeypatch.setenv('HTTP_PROXY', 'http://ambient-proxy.invalid')
    monkeypatch.setenv('KERNEL_API_KEY', 'wrong-ambient-key')
    assert client.http is not client.kernel.http and client.http.trust_env is False
    assert client.http.adapters['https://'].max_retries.total == 0
    client.http.responses = [Response(201, {'id': 'vault-fixture', 'name': 'owner-fixture', 'secret': SECRET}),
        Response(200, {'id': 'vault-fixture', 'name': 'owner-fixture'})]
    assert client.create_vault('owner-fixture') == {'id': 'vault-fixture', 'name': 'owner-fixture'}
    assert client.get_vault('vault-fixture')['name'] == 'owner-fixture'
    assert [(call[0], call[1]) for call in client.http.calls] == [
        ('POST', 'https://api.onkernel.com/vaults'),
        ('GET', 'https://api.onkernel.com/vaults/vault-fixture')]
    for _, _, kwargs in client.http.calls:
        assert kwargs['headers']['Authorization'] == 'Bearer ' + KEY
        assert kwargs['headers']['X-Kernel-Project'] == 'project-fixture'
        assert kwargs['allow_redirects'] is False


def test_create_get_update_and_delete_exact_wire_contracts(client):
    fields = [{'name': 'username', 'type': 'email', 'sensitive': False, 'value': PUBLIC},
              {'name': 'password', 'type': 'password', 'value': SECRET}]
    client.http.responses = [Response(201, credential()), Response(200, credential()),
